package org.sonatype.nexus.repository.openformats.go;
@org.springframework.stereotype.Component @org.springframework.context.annotation.Scope("prototype") @org.springframework.beans.factory.annotation.Qualifier("go") public class GoContent extends org.sonatype.nexus.repository.openformats.OpenContentFacet { public GoContent(@org.springframework.beans.factory.annotation.Qualifier("go") org.sonatype.nexus.repository.content.store.FormatStoreManager store) { super(store); } @Override protected String determineContentType(org.sonatype.nexus.repository.content.Asset asset,org.sonatype.nexus.blobstore.api.Blob blob,boolean strict) { if(asset.path().contains("/@v/")&&asset.path().endsWith(".mod"))return "text/plain";if(asset.path().contains("/@v/")&&asset.path().endsWith(".info"))return "application/json";return super.determineContentType(asset,blob,strict); } }
